MOD = 10**9 + 7

def count_random_pictures(n, m):
    if m == 1:
        return 2 ** n % MOD

    # dp[i][j] will store the number of ways to color the first i rows
    # with the j-th pattern of the last row
    dp = [[0] * (1 << m) for _ in range(n + 1)]

    # Base case: there's one way to color zero rows
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1 << m):
            valid = True
            for k in range(m):
                if (j & (1 << k)) and ((k > 0 and (j & (1 << (k - 1)))) or (k < m - 1 and (j & (1 << (k + 1))))):
                    valid = False
                    break
            if valid:
                for k in range(1 << m):
                    valid_transition = True
                    for l in range(m):
                        if (j & (1 << l)) and (k & (1 << l)):
                            valid_transition = False
                            break
                    if valid_transition:
                        dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD

    result = sum(dp[n]) % MOD
    return result

