def count_random_pictures(n, m):
    if m == 1:
        return 2 ** n % MOD
    elif m == 2:
        return 2 * (3 ** (n - 1)) % MOD
    else:
        # Initialize the transition matrix for m >= 3
        T = [[0] * (1 << m) for _ in range(1 << m)]
        for i in range(1 << m):
            for j in range(1 << m):
                if all((i & (1 << k)) != (j & (1 << k)) for k in range(m)):
                    if all((i & (1 << k)) != (i & (1 << (k + 1))) for k in range(m - 1)):
                        T[i][j] = 1

        # Initial state vector
        S = [1] * (1 << m)

        # Matrix exponentiation to find T^(n-1)
        def matrix_mult(A, B, mod):
            return [[sum(A[i][k] * B[k][j] for k in range(len(B))) % mod for j in range(len(B[0]))] for i in range(len(A))]

        def matrix_pow(matrix, power, mod):
            result = [[1 if i == j else 0 for j in range(len(matrix))] for i in range(len(matrix))]
            base = matrix
            while power > 0:
                if power % 2 == 1:
                    result = matrix_mult(result, base, mod)
                base = matrix_mult(base, base, mod)
                power //= 2
            return result

        T_n_minus_1 = matrix_pow(T, n - 1, MOD)

        # Calculate the final result
        result = sum(S[i] * sum(T_n_minus_1[i][j] for j in range(1 << m)) for i in range(1 << m)) % MOD
        return result

