def count_random_pictures(n, m):
    if m == 1:
        return 2 ** n % MOD

    # Generate all valid row configurations
    def generate_rows():
        rows = []
        for i in range(1 << m):
            valid = True
            for j in range(m - 1):
                if (i >> j) & 1 == (i >> (j + 1)) & 1:
                    valid = False
                    break
            if valid:
                rows.append(i)
        return rows

    rows = generate_rows()
    num_rows = len(rows)

    # Create the transition matrix
    transition_matrix = [[0] * num_rows for _ in range(num_rows)]
    for i in range(num_rows):
        for j in range(num_rows):
            valid = True
            for k in range(m):
                if ((rows[i] >> k) & 1) == ((rows[j] >> k) & 1):
                    valid = False
                    break
            if valid:
                transition_matrix[i][j] = 1

    # Compute the power of the transition matrix
    def matrix_multiply(A, B):
        return [[sum(A[i][k] * B[k][j] for k in range(num_rows)) % MOD for j in range(num_rows)] for i in range(num_rows)]

    def matrix_power(matrix, exp):
        result = [[1 if i == j else 0 for j in range(num_rows)] for i in range(num_rows)]
        base = matrix
        while exp > 0:
            if exp % 2 == 1:
                result = matrix_multiply(result, base)
            base = matrix_multiply(base, base)
            exp //= 2
        return result

    result_matrix = matrix_power(transition_matrix, n - 1)

    # Sum up the first row of the result matrix
    total = sum(result_matrix[0]) % MOD

    return total

