        for i in range(m - 1):
            if (mask >> i) & 1 == 1 and (mask >> (i + 1)) & 1 == 1:
                return False
        return True

    def can_transition(prev_mask, curr_mask):
        for i in range(m):
            if (prev_mask >> i) & 1 == 1 and (curr_mask >> i) & 1 == 1:
                return False
        return True

    dp = [[0] * (1 << m) for _ in range(n)]

    for mask in range(1 << m):
        if is_valid(mask):
            dp[0][mask] = 1

    for i in range(1, n):
