                if is_valid(curr_mask) and can_transition(prev_mask, curr_mask):
                    dp[i][curr_mask] = (dp[i][curr_mask] + dp[i - 1][prev_mask]) % MOD

    result = sum(dp[n - 1]) % MOD
    return result

